def self.hash_or_block_argument?(argument)
  argument.hash_type? || argument.block_pass_type?
end

def self.enabled_for_config?(config)
  cop_config = config.for_cop('Style/DigChain')
  return false unless cop_config

  cop_config['Enabled']
end

def self.ignore_single_argument_in_chain?(config, node)
  return false unless enabled_for_config?(config)
  return false unless node

  dig_call?(node.receiver) || dig_call?(node.parent)
end

