def apply_chain_correction(corrector, node, range, replacement)
  @repair_snapshot ||= {}
  @repair_snapshot[:applied] = true
  @repair_snapshot[:replacement] = replacement
  corrector.replace(range, replacement)
  comments_in_range(node).reverse_each do |comment|
    corrector.insert_before(node, "#{comment.source}\n")
  end
  @repair_snapshot[:comment_moves] = 0
  @repair_snapshot[:meta0_begin_pos] = range_begin_pos(range)
  @repair_snapshot[:meta1_end_pos] = range_end_pos(range)
